index = json.loads(INDEX.read_text(encoding='utf-8'))
index['assets'] = [a for a in index['assets'] if not a.get('asset_id','').startswith('hn03_up_')]
doc = pymupdf.open(NETTER)
placements = {}
for page, rect, plate, slug, topic, position, title, view, desc, labels in figs:
    asset_id = f'hn03_up_netter_{slug}'
    path = IMAGES / f'{asset_id}.jpeg'
    pix = doc[page-1].get_pixmap(matrix=pymupdf.Matrix(2.5,2.5), clip=pymupdf.Rect(rect), alpha=False)
    image = Image.frombytes('RGB', (pix.width,pix.height), pix.samples)
    if slug == 'clivus':
        # The next plate figure begins at the bottom edge, to the right of the
        # last label. Remove only that fragment, preserving the label descenders.
        ImageDraw.Draw(image).rectangle((int((180-rect[0])*2.5), int((486-rect[1])*2.5), pix.width, pix.height), fill='white')
    if slug == 'lambda':
        # Adjacent inferior-view figure intrudes at the lower left of the crop;
        # preserve the superior view and its leaders while removing that fragment.
        ImageDraw.Draw(image).rectangle((0, int((397-rect[1])*2.5), int((325-rect[0])*2.5), pix.height), fill='white')
    image.save(path, 'JPEG', quality=92, optimize=True)
    rel = str(path.relative_to(ROOT))
    index['assets'].append({'asset_id':asset_id,'book':'netter','session':'hn03',
        'source_file':str(NETTER.relative_to(ROOT)),'page':page,'plate':str(plate),
        'bbox':list(rect),'w':pix.width,'h':pix.height,'bytes':path.stat().st_size,'path':rel,
        **({'masked_source_rect': [180,486,590,489], 'mask_reason': 'remove fragment of adjacent lower figure'} if slug == 'clivus' else
           {'masked_source_rect': [70,397,325,425], 'mask_reason': 'remove fragment of adjacent inferior-view figure'} if slug == 'lambda' else {})})
    captions = {77:'Skull: Anterior View — Right orbit: frontal view',
        90:'Cranium: Posterior and Lateral Views', 81:'Cranium: Median Section',
        114:'Lateral Wall of Nasal Cavity of Cranium',
        79:'Skull: Lateral View — Infratemporal fossa',
        83:'Cranial Base: Inferior View', 82:'Calvaria — Superior view',
        179:'Meninges and Diploic Veins — Diploic and emissary veins of skull',
        280:'Veins of Vertebral Column: Vertebral Veins'}
    block = {'type':'plate','book':'netter','asset':rel,'title':title,
        'citation':f'نتر، پلیت {plate}، ص {page} فایل PDF','en_caption':captions[page],
        'view':view,'fa_text':desc,
        'labels':labels,'src':f'نتر، پلیت {plate}، صفحهٔ PDF {page}', 'max_h':185 if slug in ('palate', 'emissary') else 125, 'fresh':True}
    placements.setdefault((topic,position),[]).append(block)
INDEX.write_text(json.dumps(index,ensure_ascii=False,indent=1)+'\n',encoding='utf-8')

overlay = {}
for n,(page,importance,guide,key,spatial,basic) in enumerate(entries,1):
    tid=f'hn03-T{n:02}'
    blocks=base[tid]
    after={}
    def add(position, block):
        if not 0 <= position < len(blocks)-1:
            raise ValueError(f'{tid}: invalid insertion index {position}')
        after.setdefault(str(position),[]).append(block)
    src=f'جزوهٔ درس، صفحهٔ PDF {page}'
    # Explicitly additive: original blocks stay untouched and in order.
    key_src = src
    if n == 2:
        key_src += '؛ StatPearls, Sinus Function and Development (NBK532926)'
    elif n == 5:
        key_src += '؛ نتر، پلیت ۳۴، صفحهٔ PDF ۸۶'
    add(1,box('نکتهٔ کلیدی — افزودهٔ آموزشی',key,'exam',key_src))
    add(1,box('علوم پایه — افزودهٔ آموزشی',basic,'info',src))
    # Place spatial advice immediately after the later of the first two content
    # blocks; further image captions carry local orientation.
    add(2,box('راهنمای درک فضایی — افزودهٔ آموزشی',spatial,'info',src))
    if n in tables:
        pos, value=tables[n]; add(pos,value)
    for (topic,pos), values in placements.items():
        if topic == n:
            for value in values: add(pos,value)
    overlay[tid]={'card_rows':[{'label':'اهمیت و کاربرد','text':importance},
                               {'label':'راهنمای خواندن شکل','text':guide}], 'after':after}
(CONTENT/'hn03_update.json').write_text(json.dumps({'version':1,'status':'work in progress; transcription and visual QA incomplete',
       'topics':overlay},ensure_ascii=False,indent=1)+'\n',encoding='utf-8')
print(f'{len(overlay)} topics, {len(entries)*3} callouts, {len(tables)} tables, {len(figs)} atlas crops')
